    if let Some(t) = self.scan_number() {
        return Some(t);
    }
    if let Some(t) = self.scan_string().ok().flatten() {
        return Some(t);
    }
    if let Some(t) = self.scan_symbol() {
        return Some(t);
    }
    None
}

